(1, 3, 'Biểu mẫu E-Form Đơn xin cấp Giấy phép xây dựng', '1.0', '{"tieu_de": "Đơn xin cấp giấy phép xây dựng nhà ở riêng lẻ đô thị", "fields": [{"name": "nguoi_nop_ho_ten", "label": "Họ và tên chủ đầu tư", "type": "text", "required": true, "vneid_field": "ho_ten", "readonly": true}, {"name": "nguoi_nop_cccd", "label": "Số thẻ CCCD", "type": "text", "required": true, "vneid_field": "so_cccd", "readonly": true}, {"name": "nguoi_nop_sdt", "label": "Số điện thoại liên hệ", "type": "tel", "required": true, "vneid_field": "so_dien_thoai"}, {"name": "nguoi_nop_dia_chi", "label": "Địa chỉ thường trú", "type": "text", "required": true, "vneid_field": "dia_chi_thuong_tru", "readonly": true}, {"name": "dia_diem_xay_dung", "label": "Địa điểm xây dựng công trình (Số nhà, đường, phường)", "type": "text", "required": true}, {"name": "so_thua_dat", "label": "Số thửa đất", "type": "text", "required": true}, {"name": "so_to_ban_do", "label": "Số tờ bản đồ", "type": "text", "required": true}, {"name": "dien_tich_xay_dung", "label": "Diện tích xây dựng tầng 1 (m2)", "type": "number", "required": true}, {"name": "tong_dien_tich_san", "label": "Tổng diện tích sàn xây dựng (m2)", "type": "number", "required": true}, {"name": "chieu_cao_cong_trinh", "label": "Chiều cao công trình (m)", "type": "number", "required": true}, {"name": "so_tang", "label": "Số tầng", "type": "number", "required": true}]}', 1),
(2, 7, 'Biểu mẫu E-Form Đề xuất Dự án Đầu tư Logistics Cảng biển', '1.0', '{"tieu_de": "Tờ khai đề xuất dự án đầu tư logistics cảng biển Hải Phòng", "fields": [{"name": "ten_doanh_nghiep", "label": "Tên doanh nghiệp đề xuất", "type": "text", "required": true}, {"name": "ma_so_thue", "label": "Mã số thuế doanh nghiệp", "type": "text", "required": true}, {"name": "nguoi_dai_dien", "label": "Người đại diện theo pháp luật", "type": "text", "required": true, "vneid_field": "ho_ten"}, {"name": "dia_chi_tru_so", "label": "Địa chỉ trụ sở chính", "type": "text", "required": true}, {"name": "ten_du_an", "label": "Tên dự án logistics cảng biển", "type": "text", "required": true}, {"name": "dia_diem_thuc_hien", "label": "Địa điểm thực hiện dự án (Khu vực Cảng/KCN)", "type": "select", "options": ["KKT Đình Vũ - Cát Hải", "KCN Nam Cầu Kiền", "KCN DEEP C Hải Phòng", "KCN VSIP Hải Phòng"], "required": true}, {"name": "tong_von_dau_tu", "label": "Tổng vốn đầu tư dự kiến (VND)", "type": "number", "required": true}, {"name": "quy_mo_cong_suat", "label": "Quy mô công suất thiết kế (TEU/năm hoặc Tấn/năm)", "type": "text", "required": true}, {"name": "nhu_cau_su_dung_dat", "label": "Nhu cầu sử dụng đất (ha)", "type": "number", "required": true}]}', 1);
